<?php
namespace App\Services; use App\Models\CmsPage; use Illuminate\Support\Str; use Illuminate\View\View;
class CmsPageService { public function public(string $slug):CmsPage{return CmsPage::query()->public()->with(['sections.faqItems'=>fn($q)=>$q->where('is_active',true)])->where('slug',$slug)->firstOrFail();} public function slug(string $value,?CmsPage $ignore=null):string{$base=Str::slug($value)?:'page';$reserved=['admin','vendor','account','login','register','sell','cart','checkout','orders','products','categories','brands','stores','search','api','pages']; abort_if(in_array($base,$reserved,true),422,'This slug is reserved.');$candidate=$base;$i=2;while(CmsPage::where('slug',$candidate)->when($ignore,fn($q)=>$q->whereKeyNot($ignore->id))->exists())$candidate=$base.'-'.$i++;return $candidate;} }
